-- Holistic House Psychic Health Monitoring R1
-- Additive: structured mood check-ins + immutable assessment versions.
begin;

create table app.mood_checkins(
  id uuid primary key default gen_random_uuid(),
  account_id uuid not null references app.accounts(id) on delete cascade,
  mood text not null check(mood in('sad','neutral','happy')),
  category text check(category is null or category in('body','energy','emotions','relationships','work-money','other')),
  occurred_at timestamptz not null,
  timezone text not null check(char_length(timezone) between 1 and 100),
  source_surface text not null check(source_surface in('cabinet_landing','portrait','tests')),
  operation_id uuid not null,
  created_at timestamptz not null default now(),
  unique(account_id,operation_id)
);
create index mood_checkins_account_time on app.mood_checkins(account_id,occurred_at desc,id desc);
alter table app.mood_checkins enable row level security;
revoke all on app.mood_checkins from public,anon,authenticated,hh_app_inbox;
grant select on app.mood_checkins to authenticated,hh_app_backend;
grant insert on app.mood_checkins to hh_app_backend;
create policy own_mood_checkins_read on app.mood_checkins
  for select to authenticated,hh_app_backend
  using(account_id=(select auth.uid()) and (select app_private.account_active()));
create policy own_mood_checkins_create on app.mood_checkins
  for insert to hh_app_backend
  with check(account_id=(select auth.uid()) and (select app_private.account_active()));

create table app_private.guest_mood_checkins(
  id uuid primary key default gen_random_uuid(),
  guest_session_id uuid not null references app_private.guest_sessions(id) on delete cascade,
  mood text not null check(mood in('sad','neutral','happy')),
  category text check(category is null or category in('body','energy','emotions','relationships','work-money','other')),
  occurred_at timestamptz not null,
  timezone text not null check(char_length(timezone) between 1 and 100),
  source_surface text not null check(source_surface in('cabinet_landing','portrait','tests')),
  operation_id uuid not null,
  expires_at timestamptz not null,
  created_at timestamptz not null default now(),
  unique(guest_session_id,operation_id)
);
create index guest_mood_checkins_session_time
  on app_private.guest_mood_checkins(guest_session_id,occurred_at desc,id desc);
alter table app_private.guest_mood_checkins enable row level security;
revoke all on app_private.guest_mood_checkins from public,anon,authenticated,hh_app_inbox;
grant select,insert,delete on app_private.guest_mood_checkins to hh_app_backend;
create policy guest_mood_backend_all on app_private.guest_mood_checkins
  for all to hh_app_backend using(true) with check(true);

