    ) as v(id,definition,content_hash,answer_schema)
  loop
    if exists(select 1 from app.assessment_versions where id=r.id and content_hash<>r.content_hash) then
      raise exception 'Published psychic monitoring definition % differs from reviewed definition',r.id;
    end if;
    insert into app.assessment_versions(
      id,definition_key,definition_version,instrument_locale,translation_version,
      definition,questions,answer_schema,scoring_key,scoring_version,result_schema,
      timeframe,source_metadata,content_hash
    )
    values(
      r.id,r.definition->>'key',r.definition->>'version',r.definition->>'instrumentLocale',
      r.definition->>'translationVersion',r.definition,r.definition->'questions',r.answer_schema,
      r.definition->>'scoringKey',r.definition->>'scoringVersion',
      jsonb_build_object('version',r.definition->>'resultVersion'),
      r.definition->>'timeframe',r.definition->'source',r.content_hash
    )
    on conflict(id) do nothing;
  end loop;
end $$;

